// Definição dos valores nominais e dos deltas ajustáveis
double VQ_nominal = 1.0;       // Tensão de repouso nominal (V)
double S_nominal = 0.045;      // Sensibilidade nominal (V/mT)

// Parâmetros ajustáveis ( ΔV_Q e ΔS ) conforme o caso simulado
// Exemplo para o caso nominal: delta_VQ = 0.0, delta_S = 0.0
// Exemplo para pior caso positivo: delta_VQ = 0.15, delta_S = 0.025 (total 0.070)
// Exemplo para pior caso negativo: delta_VQ = -0.10, delta_S = -0.025 (total 0.020)
double delta_VQ = 0.15;         // Altere conforme o ensaio (ex: 0.15 ou -0.10)
double delta_S = 0.025;          // Altere conforme o ensaio (ex: 0.025 ou -0.025)

// Cálculo da tensão do sensor com as não idealidades estáticas
double VQ_real = VQ_nominal + delta_VQ;
double S_real = S_nominal + delta_S;

// Equação final da camada estática
V_sensor = VQ_real + (S_real * B);
/*End code section*/
